import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Box, Typography, Button, Grid, CircularProgress, Alert, Stepper, Step,
  StepLabel, Paper, Divider, FormControl, InputLabel, Select, MenuItem,
  TextField, Chip, IconButton, Avatar,
} from '@mui/material';
import SaveIcon from '@mui/icons-material/Save';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import CloseIcon from '@mui/icons-material/Close';
import InsertDriveFileIcon from '@mui/icons-material/InsertDriveFile';
import JalaliDatePicker from '../core/components/ui/JalaliDatePicker';
import StatusBadge from '../core/components/ui/StatusBadge';
import {
  useEmployee, useCreateEmployee, useUpdateEmployee,
  useDepartments, useJobTitles, useWorkLocations, useInsuranceLists
} from '../core/hooks/useEmployees';
import { useDocumentTypes, useUploadDocument, useDocuments, useDeleteDocument } from '../core/hooks/useDocuments';

const STEPS = ['اطلاعات فردی', 'اطلاعات تماس', 'اطلاعات شغلی', 'مدارک'];

const EMPTY_FORM = {
  first_name: '', last_name: '', national_id: '', birth_date: '', birth_place: '',
  gender: '', marital_status: '', children_count: 0, spouse_name: '',
  national_id_serial: '', national_id_place: '', national_id_date: '',
  phone: '', mobile: '', email: '', address: '', postal_code: '',
  emergency_contact_name: '', emergency_contact_phone: '',
  employee_id: '', hire_date: '', probation_end_date: '', official_date: '',
  department: '', job_title: '', work_location: '', insurance_list: '',
  contract_type: '', contract_start_date: '', contract_end_date: '',
  status: 'active', status_change_date: '', work_shift: '', description: '',
};

const selectField = (label, field, value, onChange, options = [], t) => (
  <Grid item xs={12} sm={6} md={4}>
    <FormControl fullWidth size="small">
      <InputLabel>{label}</InputLabel>
      <Select value={value || ''} label={label} onChange={e => onChange(field, e.target.value)}>
        {options.map(opt => <MenuItem key={opt.value} value={opt.value}>{opt.label}</MenuItem>)}
      </Select>
    </FormControl>
  </Grid>
);

const textField = (label, field, value, onChange, required = false, type = 'text') => (
  <Grid item xs={12} sm={6} md={4}>
    <TextField fullWidth size="small" label={label} type={type} value={value || ''}
      onChange={e => onChange(field, e.target.value)} required={required}
      InputLabelProps={type === 'date' ? { shrink: true } : {}} />
  </Grid>
);

const dateField = (label, field, value, onChange) => (
  <Grid item xs={12} sm={6} md={4}>
    <JalaliDatePicker fullWidth label={label} value={value}
      onChange={gregorian => onChange(field, gregorian)} />
  </Grid>
);

const EmployeeForm = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = Boolean(id);
  const [step, setStep] = useState(0);

  const [form, setForm] = useState(EMPTY_FORM);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  const { data: employee, isLoading: loadingEmployee } = useEmployee(id);
  const { data: departments } = useDepartments();
  const { data: jobTitles } = useJobTitles();
  const { data: workLocations } = useWorkLocations();
  const { data: insuranceLists } = useInsuranceLists();
  const { data: docTypes } = useDocumentTypes();
  const { data: existingDocs } = useDocuments(id);
  const createMutation = useCreateEmployee();
  const updateMutation = useUpdateEmployee();
  const uploadDocMutation = useUploadDocument();
  const deleteDocMutation = useDeleteDocument();

  // Local doc upload state
  const [pendingFiles, setPendingFiles] = useState([]);
  const [pendingDocType, setPendingDocType] = useState('');
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (employee) {
      setForm(prev => ({ ...prev, ...employee }));
    }
  }, [employee]);

  const handleChange = (field, value) => setForm(prev => ({ ...prev, [field]: value }));

  const handleSubmit = async () => {
    setError('');
    setSubmitting(true);
    try {
      let empId = id;
      if (isEdit) {
        await updateMutation.mutateAsync({ id, data: form });
      } else {
        const result = await createMutation.mutateAsync(form);
        empId = result.id;
      }

      // Upload pending files
      if (pendingFiles.length > 0 && empId) {
        setUploading(true);
        for (const f of pendingFiles) {
          const fd = new FormData();
          fd.append('employee', empId);
          fd.append('title', f.name);
          fd.append('document_type', f.docType || '');
          fd.append('file', f);
          await uploadDocMutation.mutateAsync(fd);
        }
        setUploading(false);
      }

      setSuccess(true);
      setTimeout(() => navigate(`/employees/${empId}`), 1000);
    } catch (err) {
      setError(err.response?.data?.detail || t('employees.save_error'));
    } finally {
      setSubmitting(false);
    }
  };

  const addFileToPending = (e) => {
    const files = Array.from(e.target.files || []);
    setPendingFiles(prev => [...prev, ...files]);
  };

  const removePendingFile = (index) => {
    setPendingFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleDeleteDoc = (docId) => {
    if (window.confirm(t('documents.delete_confirm'))) deleteDocMutation.mutate(docId);
  };

  const GENDERS = [{ value: 'male', label: t('employees.male') }, { value: 'female', label: t('employees.female') }];
  const MARITAL = [{ value: 'single', label: t('employees.single') }, { value: 'married', label: t('employees.married') }, { value: 'divorced', label: t('employees.divorced') }, { value: 'widowed', label: t('employees.widowed') }];
  const CONTRACT = [{ value: 'permanent', label: t('employees.permanent') }, { value: 'temporary', label: t('employees.temporary') }, { value: 'project', label: t('employees.project') }, { value: 'contractor', label: t('employees.contractor') }];
  const STATUSES = [{ value: 'active', label: t('employees.active') }, { value: 'leave', label: t('employees.on_leave') }, { value: 'retired', label: t('employees.retired') }, { value: 'terminated', label: t('employees.terminated') }, { value: 'deceased', label: t('employees.deceased') }];
  const SHIFTS = [{ value: 'morning', label: t('employees.morning') }, { value: 'evening', label: t('employees.evening') }, { value: 'rotating', label: t('employees.rotating') }, { value: 'irregular', label: t('employees.irregular') }];
  const mapOpts = (data) => Array.isArray(data) ? data.map(d => ({ value: d.id, label: d.name })) : [];

  const isLoading = isEdit && loadingEmployee;
  if (isLoading) return <Box sx={{ textAlign: 'center', p: 6 }}><CircularProgress /></Box>;

  if (success) {
    return (
      <Box sx={{ textAlign: 'center', p: 8 }}>
        <Typography variant="h4" color="success.main">✅ {t('employees.save_success')}</Typography>
        <Typography color="textSecondary">در حال انتقال به پروفایل...</Typography>
      </Box>
    );
  }

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <Grid container spacing={2}>
            {textField(t('employees.first_name'), 'first_name', form.first_name, handleChange, true)}
            {textField(t('employees.last_name'), 'last_name', form.last_name, handleChange, true)}
            {textField(t('employees.national_id'), 'national_id', form.national_id, handleChange, true)}
            {dateField(t('employees.birth_date'), 'birth_date', form.birth_date, handleChange)}
            {textField(t('employees.birth_place'), 'birth_place', form.birth_place, handleChange)}
            {selectField(t('employees.gender'), 'gender', form.gender, handleChange, GENDERS, t)}
            {selectField(t('employees.marital_status'), 'marital_status', form.marital_status, handleChange, MARITAL, t)}
            {textField(t('employees.children_count'), 'children_count', form.children_count, handleChange, false, 'number')}
            {textField(t('employees.spouse_name'), 'spouse_name', form.spouse_name, handleChange)}
            {textField(t('employees.national_id_serial'), 'national_id_serial', form.national_id_serial, handleChange)}
            {textField(t('employees.national_id_place'), 'national_id_place', form.national_id_place, handleChange)}
            {dateField(t('employees.national_id_date'), 'national_id_date', form.national_id_date, handleChange)}
          </Grid>
        );
      case 1:
        return (
          <Grid container spacing={2}>
            {textField(t('employees.phone'), 'phone', form.phone, handleChange)}
            {textField(t('employees.mobile'), 'mobile', form.mobile, handleChange, true)}
            {textField(t('employees.email'), 'email', form.email, handleChange)}
            <Grid item xs={12}>
              <TextField fullWidth size="small" label={t('employees.address')} value={form.address || ''}
                onChange={e => handleChange('address', e.target.value)} multiline rows={2} />
            </Grid>
            {textField(t('employees.postal_code'), 'postal_code', form.postal_code, handleChange)}
            {textField(t('employees.emergency_contact_name'), 'emergency_contact_name', form.emergency_contact_name, handleChange)}
            {textField(t('employees.emergency_contact_phone'), 'emergency_contact_phone', form.emergency_contact_phone, handleChange)}
          </Grid>
        );
      case 2:
        return (
          <Grid container spacing={2}>
            {textField(t('employees.employee_id'), 'employee_id', form.employee_id, handleChange, true)}
            {dateField(t('employees.hire_date'), 'hire_date', form.hire_date, handleChange)}
            {dateField(t('employees.probation_end_date'), 'probation_end_date', form.probation_end_date, handleChange)}
            {dateField(t('employees.official_date'), 'official_date', form.official_date, handleChange)}
            {selectField(t('employees.department'), 'department', form.department, handleChange, mapOpts(departments), t)}
            {selectField(t('employees.job_title'), 'job_title', form.job_title, handleChange, mapOpts(jobTitles), t)}
            {selectField(t('employees.work_location'), 'work_location', form.work_location, handleChange, mapOpts(workLocations), t)}
            {selectField(t('employees.insurance_list'), 'insurance_list', form.insurance_list, handleChange, mapOpts(insuranceLists), t)}
            {selectField(t('employees.contract_type'), 'contract_type', form.contract_type, handleChange, CONTRACT, t)}
            {dateField(t('employees.contract_start_date'), 'contract_start_date', form.contract_start_date, handleChange)}
            {dateField(t('employees.contract_end_date'), 'contract_end_date', form.contract_end_date, handleChange)}
            {selectField(t('employees.status'), 'status', form.status, handleChange, STATUSES, t)}
            {dateField(t('employees.status_change_date'), 'status_change_date', form.status_change_date, handleChange)}
            {selectField(t('employees.work_shift'), 'work_shift', form.work_shift, handleChange, SHIFTS, t)}
            <Grid item xs={12}>
              <TextField fullWidth size="small" label={t('employees.description')} multiline rows={3}
                value={form.description || ''} onChange={e => handleChange('description', e.target.value)} />
            </Grid>
          </Grid>
        );
      case 3:
        return (
          <Box>
            <Typography variant="body1" sx={{ mb: 2 }}>
              مدارک پرسنل — می‌توانید چند فایل انتخاب کنید. پس از ذخیره نهایی آپلود می‌شوند.
            </Typography>

            {/* Existing documents (edit mode) */}
            {isEdit && existingDocs && existingDocs.length > 0 && (
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>مدارک موجود:</Typography>
                {existingDocs.map(doc => (
                  <Chip key={doc.id} label={`${doc.title} (${doc.document_type_name})`} size="small"
                    onDelete={() => handleDeleteDoc(doc.id)} sx={{ m: 0.5 }} />
                ))}
              </Box>
            )}

            {/* Pending files */}
            {pendingFiles.length > 0 && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="subtitle2" gutterBottom>فایل‌های انتخاب‌شده:</Typography>
                {pendingFiles.map((f, i) => (
                  <Paper key={i} variant="outlined" sx={{ p: 1, mb: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
                    <InsertDriveFileIcon fontSize="small" color="primary" />
                    <Typography variant="body2" sx={{ flexGrow: 1 }}>{f.name} ({(f.size / 1024).toFixed(0)} KB)</Typography>
                    <FormControl size="small" sx={{ minWidth: 140 }}>
                      <Select value={f.docType || ''} displayEmpty
                        onChange={e => {
                          const updated = [...pendingFiles];
                          updated[i].docType = e.target.value;
                          setPendingFiles(updated);
                        }}>
                        <MenuItem value="">نوع مدرک</MenuItem>
                        {Array.isArray(docTypes) && docTypes.map(dt => <MenuItem key={dt.id} value={dt.id}>{dt.name}</MenuItem>)}
                      </Select>
                    </FormControl>
                    <IconButton size="small" onClick={() => removePendingFile(i)}><CloseIcon fontSize="small" /></IconButton>
                  </Paper>
                ))}
              </Box>
            )}

            <Paper variant="outlined" sx={{
              p: 4, textAlign: 'center', cursor: 'pointer', borderStyle: 'dashed',
              transition: 'all 0.2s', '&:hover': { borderColor: 'primary.main', bgcolor: 'rgba(99,102,241,0.04)' }
            }} onClick={() => document.getElementById('multi-file-input').click()}>
              <input id="multi-file-input" type="file" multiple hidden onChange={addFileToPending} />
              <CloudUploadIcon sx={{ fontSize: 40, color: 'primary.main', mb: 1 }} />
              <Typography variant="body2" color="textSecondary">{t('documents.drag_drop')}</Typography>
              <Typography variant="caption" color="textSecondary">PDF, JPG, PNG, DOCX (حداکثر ۱۰MB)</Typography>
            </Paper>
          </Box>
        );
      default:
        return null;
    }
  };

  return (
    <Box component="form" onSubmit={e => { e.preventDefault(); if (step < 3) setStep(s => s + 1); else handleSubmit(); }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, gap: 2 }}>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/employees')}>{t('common.back')}</Button>
        <Typography variant="h4">{isEdit ? t('employees.edit_employee') : t('employees.add_employee')}</Typography>
      </Box>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      <Paper sx={{ p: 3, mb: 2 }}>
        <Stepper activeStep={step} alternativeLabel sx={{ mb: 3 }}>
          {STEPS.map(label => <Step key={label}><StepLabel>{label}</StepLabel></Step>)}
        </Stepper>
        <Divider sx={{ mb: 3 }} />
        {renderStep()}
      </Paper>

      <Box sx={{ display: 'flex', gap: 2, justifyContent: 'space-between' }}>
        <Button variant="outlined" onClick={() => navigate('/employees')}>{t('common.cancel')}</Button>
        <Box sx={{ display: 'flex', gap: 1 }}>
          {step > 0 && <Button variant="outlined" startIcon={<ArrowBackIcon />} onClick={() => setStep(s => s - 1)}>قبلی</Button>}
          {step < 3 ? (
            <Button variant="contained" endIcon={<ArrowForwardIcon />}
              onClick={() => setStep(s => s + 1)}>بعدی</Button>
          ) : (
            <Button type="submit" variant="contained" startIcon={<SaveIcon />} disabled={submitting || uploading}
              onClick={handleSubmit}>
              {(submitting || uploading) ? <CircularProgress size={20} /> : t('common.save')}
            </Button>
          )}
        </Box>
      </Box>
    </Box>
  );
};

export default EmployeeForm;
